/** The class names are generated by docx-preview from Word paragraph style IDs. */
export function getWordHeadingLevel(node: HTMLElement): number | null {
  const headingTag = /^H([1-6])$/.exec(node.tagName);
  if (headingTag) return Number(headingTag[1]);
  if (node.tagName !== "P") return null;

  for (const className of node.classList) {
    const style = /(?:^|_)(heading|encabezado|title|titulo|título|subtitle|subtitulo|subtítulo)(?:[-_]?([1-9]))?$/i.exec(
      className,
    );
    if (!style) continue;
    const [, kind, number] = style;
    if (/^sub/i.test(kind)) return 1;
    if (/^(?:title|t[ií]tulo)$/i.test(kind) && !number) return 0;
    return Number(number || 1);
  }
  return null;
}
